  if (o.hi) feDraw(r, P, { heat: false, color: o.hi, w: s, alpha: a * (o.hk == null ? 1 : o.hk), seg: 1, hide: e => PLT_GEO.members[e][2] !== 1, fillet: Math.max(1.5, 0.35 * s) });
  for (const b of PLT_GEO.bosses) { const q = P(b); circle(q[0], q[1], 3.1 * s, { fill: o.hi && o.hk > 0.5 ? o.hi : PLT_COL.rib(), alpha: a }); }
  G.restore();
  plt_fill(() => plt_stad(P, Wn.c, Wn.hw, Wn.hl), TH ? '#0B0C0E' : '#050506', null, 0, a);
  for (const [x, z] of PLT_GEO.screws) { const q = P([x, z]); circle(q[0], q[1], 1.1 * s, { fill: TH ? '#0B0C0E' : '#050506', alpha: a }); }
  plt_fill(() => plt_path(P, PLT_GEO.outline), null, inkA(0.5), 1.5, a);
