/** the headline: a label, a huge figure in Theseus's gradient, a line under it */
function plt_head(t, t0, x, y, value, unit, o = {}) {
  const a = ep(t, t0, t0 + 0.5); if (a <= 0.003) return;
  const size = o.size || 200;
  if (o.label) text(o.label, x, y - size * 0.8 - 18, { role: 'label', size: 22, color: C.heroText, alpha: a, maxW: o.maxW });
  rich([{ s: value, role: 'd1', size, weight: 800, track: -0.035, color: C.heroText, grad: C.heroGrad, tnum: true }, unit ? { s: unit, font: 'disp', size: Math.round(size * 0.34), weight: 800, color: C.heroText, grad: C.heroGrad, gap: Math.round(size * 0.05) } : null], x, y, { t, alpha: a });
  if (o.sub) text(o.sub, x, y + Math.round(size * 0.24 + 30), { role: 'small', size: 26, weight: 600, color: C.ink2, alpha: ep(t, t0 + 0.3, t0 + 0.8), maxW: o.maxW || 560, lh: 1.3 });
}
/** before -> after: the old value struck in grey, an arrow, the new in Theseus's colour, the net change under it */
function plt_ba(t, t0, x, y, before, after, o = {}) {
  const a = ep(t, t0, t0 + 0.5); if (a <= 0.003) return;
  const size = o.size || 60, st0 = { role: 'd1', size, weight: 800, color: C.faint, tnum: true }, wB = tw(before, st0);
  if (o.label) text(o.label, x, y - size * 0.82 - 16, { role: 'label', size: 21, color: C.mute, alpha: a, maxW: o.maxW });
  text(before, x, y, Object.assign({ alpha: a * 0.9 }, st0));
  line(x - 4, y - size * 0.3, x + wB + 4, y - size * 0.3, { color: C.faint, w: Math.max(3, size * 0.06), alpha: a * ep(t, t0 + 0.35, t0 + 0.7) });
  const ax = x + wB + size * 0.32;
  arrow(ax, y - size * 0.32, ax + size * 0.62, y - size * 0.32, { color: C.mute, w: Math.max(2.5, size * 0.05), hs: size * 0.22, alpha: a, p: ep(t, t0 + 0.2, t0 + 0.7) });
  const k = ep(t, t0 + 0.45, t0 + 0.95);
  text(after, ax + size * 0.86, y, { role: 'd1', size, weight: 800, color: C.heroText, tnum: true, alpha: a * k });
  if (o.net) text(o.net, x, y + 40, { role: 'label', size: 21, color: C.heroText, alpha: a * k });
}

/* ============================== the plate, outside and in ============================== */
S({
  id: 'pltPlate', ch: 'shell', theme: 'paper', title: 'Bottom plate: solid outside, triangles inside', settle: 10, after: 'shlsheet2', ideas: [31, 75, 11],
  src: ['plt_brock', 'plt_fe'], three: ['shell'],
  draw: t => {
    header(t, 'Bottom plate: solid outside, triangles inside');
    captions(t, [[0.6, 'From outside the optional plate is one solid face, with no holes even before a sticker. The pills and the lens ring sit on it.'], [5.0, 'Turn it over and the strength is inside: an X from the lens to the four screws, closed into triangles, over a fine lattice.']]);
    const x = LM, y = 280, w = 1080, h = 680, kf = ep(t, 3.4, 6.2, E.io3);
    demoWindow(x, y, w, h, tileA(t, 0.15, 0));
    cardHead(t, 0.35, x, y, w, kf < 0.5 ? 'The plate from below' : 'The same plate, turned over', []);
    /* the pointer takes the plate's edge and turns it */
    if (V2D.on) {
      const s = 5.4, cx = x + w / 2, cy = y + h / 2 + 22, sx = Math.cos(Math.PI * kf), aIn = kf > 0.5 ? 1 : 0;
      G.save(); G.translate(cx, 0); G.scale(Math.max(0.02, Math.abs(sx)), 1); G.translate(-cx, 0);
      if (aIn) plt_inner(cx, cy, s, ep(t, 0.5, 1.0), { hi: C.hero, hk: ep(t, 6.6, 7.4) }); else plt_outer(cx, cy, s, ep(t, 0.5, 1.0));
      G.restore();
    } else {
      view3D('shell', t, x + 10, y + 50, w - 20, h - 60, { view: 'bottom', plateFlip: kf, zoom: 1.32 + 0.05 * ep(t, 0.4, 9, E.cam), target: [0, -13 * kf, 0], colorway: 'black' }, { alpha: ep(t, 0.4, 1.0) });
    }
    cursorAt(t, [[2.6, [x + w / 2 + 330, y + 240]], [3.3, [x + w / 2 + 150, y + 330]], [6.2, [x + w / 2 - 150, y + 330]], [7.0, [x + w - 120, y + 140]]], [3.35], { a: ep(t, 2.4, 2.7) * (1 - ep(t, 6.6, 7.0)) });
    /* the right column: what each part does */
    const rx = 1240, rw = RM - rx;
    const rows = [
      [0.9, 'Outside', 'One solid face. Dust and liquid stay out, and the skates stick to all of it.', false],
      [5.4, 'The X and the keel', 'Struts from the lens ring straight to the four screws: the shortest load paths.', true],
      [6.3, 'Closed into triangles', 'Ties along the screw lines and a wall round the edge make every bay a triangle.', true],
      [7.2, 'The fine lattice', 'Each bay cut three ways, as a geodesic dome is. Every cell is a filleted copy of its bay.', true]
    ];
    rows.forEach(([t0, head, body, hero], i) => {
      const yy = y + 10 + i * 140, a = ep(t, t0, t0 + 0.5);
      if (a <= 0.003) return;
      rect(rx, yy - 4, 28 * E.out3(a), 3, { fill: hero ? C.hero : acc(), alpha: a });
      text(head, rx + 42, yy + 8, { role: 'label', size: 22, color: hero ? C.heroText : C.ink, alpha: a });
      text(body, rx, yy + 52, { role: 'small', size: 25, weight: 600, color: C.ink2, maxW: rw, lh: 1.3, alpha: a, t, t0: t0 + 0.1, cps: 140 });
    });
    const tk = ep(t, 8.0, 8.5);
    if (tk > 0.003) {
      text('Holes outside', rx, y + h - 96, { role: 'label', size: 21, color: C.heroText, alpha: tk });
      text('0', rx, y + h - 26, { role: 'd1', size: 64, weight: 800, color: C.heroText, grad: C.heroGrad, tnum: true, alpha: tk });
      text('As drawn, with fillets', rx + 280, y + h - 96, { role: 'label', size: 21, color: C.mute, alpha: tk });
      rich([{ s: PLT_GEO.mass.toFixed(2), role: 'd1', size: 64, weight: 800, color: C.ink, tnum: true }, { s: 'g', font: 'disp', size: 30, weight: 800, color: C.ink, gap: 8 }], rx + 280, y + h - 26, { alpha: tk });
    }
    source(t, 'The plate is the 3D shell\'s own, meshed from its layout: a 0.40 mm skin, 2.3 mm ribs, the X and the edge walls sized by stress (0.5 to 1.1 mm), the lattice 0.35 to 0.55 mm.', { t0: 2 });
  }
});

/* ============================== the same weight, three ways ============================== */
S({
  id: 'pltSim', ch: 'shell', theme: 'night', title: 'Bottom plate stiffness at the same weight', settle: 10, after: 'pltPlate', ideas: [31, 75],
  src: ['plt_fe', 'plt_strength'],
  draw: t => {
    header(t, 'Bottom plate stiffness at the same weight');
    captions(t, [[0.6, 'Press a plate at the lens and it bows toward the pad. All three weigh 3.40 g and are held by the same four screws.'], [5.4, 'Mine puts the weight into tall walls on the paths to the screws, closed into triangles: 6.6 times as stiff as a solid plate.']]);
    const FE = PLT_FE, ratio = FE.plain.lens / FE.theseus.lens, k = ep(t, 1.8, 3.4, E.io3), smax = FE.plain.max;
    /* ---- the glance: the headline and the flex, before -> after ---- */
    plt_head(t, 3.6, LM, 520, ratio.toFixed(1), '×', { label: 'Stiffer, the same weight', size: 210, sub: 'Than a solid plate, pressed at the lens. A plain grid matches the stiffness, with a higher peak.', maxW: 520 });
    plt_ba(t, 4.2, LM, 790, FE.plain.lens + ' µm', FE.theseus.lens + ' µm', { size: 56, label: 'Flex at the lens, solid plate to Theseus', net: '−' + Math.round((1 - FE.theseus.lens / FE.plain.lens) * 100) + '% flex' });
    text('It breaks at ' + Math.round(120 / FE.theseus.max * 10) + ' N, against ' + Math.round(120 / FE.grid.max * 10) + ' N for the grid and ' + Math.round(120 / FE.plain.max * 10) + ' N for the solid plate (120 MPa).', LM, 880, { role: 'small', size: 25, weight: 600, color: C.ink2, maxW: 540, lh: 1.3, alpha: ep(t, 5.0, 5.5) });
    /* ---- the simulation: three plates, the same press, coloured by stress on one scale ---- */
    const X0 = 680, Y0 = 280, PW = 360, PH = 520, gap = 40, s = 3.75;
    const sets = [['plain', 'Solid plate', '0.86 mm, no ribs'], ['grid', 'Plain grid', '8 mm squares'], ['theseus', 'Theseus', 'X and triangles']];
    sets.forEach(([key, nm, sub], i) => {
      const x = X0 + i * (PW + gap), hero = key === 'theseus', a = tileA(t, 0.15, i);
      demoWindow(x, Y0, PW, PH, a, { hero });
      text(nm, x + 24, Y0 + 44, { role: 'label', size: 22, color: hero ? C.heroText : C.ink, alpha: a });
      text(sub, x + 24, Y0 + 76, { role: 'small', size: 25, weight: 600, color: C.mute, alpha: a });
      const cx = x + PW / 2, cy = Y0 + 104 + 196;
      const P = plt_heat(key, cx, cy, s, k, smax, ep(t, 0.5 + i * 0.15, 1.1 + i * 0.15));
      /* the four screws hold it; the press at the lens */
      for (const b of PLT_GEO.bosses) { const q = P(b); G.save(); G.globalAlpha = a; G.fillStyle = C.mute; G.beginPath(); G.moveTo(q[0], q[1] - 6); G.lineTo(q[0] - 6, q[1] + 5); G.lineTo(q[0] + 6, q[1] + 5); G.closePath(); G.fill(); G.restore(); }
      for (const dz of [-7, 0, 7]) { const q = P([0, dz]); arrow(q[0] + 30, q[1] - 26, q[0] + 7, q[1] - 4, { color: C.ink, w: 2.5, hs: 9, alpha: ep(t, 1.6, 2.0) * (0.4 + 0.6 * k) }); }
    });
    /* ---- the numbers, one chart per measure under the plates, each saying which way is better ---- */
    const charts = [['Flex at the lens (lower is better)', 'lens', ' µm', 0], ['Peak experienced stress (lower is better)', 'max', ' MPa', 1]];
    charts.forEach(([lab, f, unit, j]) => {
      const cxL = X0 + j * 600, cy0 = Y0 + PH + 52, cw = 560, kk = ep(t, 3.2 + j * 0.3, 4.0 + j * 0.3), a = ep(t, 3.0 + j * 0.3, 3.4 + j * 0.3);
      if (a <= 0.003) return;
      text(lab, cxL, cy0, { role: 'label', size: 19, color: C.mute, alpha: a });
      sets.forEach(([key, nm], i) => {
        const v = FE[key][f], vmax = FE.plain[f], hero = key === 'theseus', yy = cy0 + 30 + i * 34, bx = cxL + 150, bw = cw - 150 - 110;
        text(nm, cxL, yy + 9, { role: 'label', size: 19, color: hero ? C.heroText : C.mute, alpha: a });
        rr(bx, yy - 2, bw, 14, 7, C.track, null, 0, a);
        rr(bx, yy - 2, Math.max(14, bw * (v / vmax) * kk), 14, 7, hero ? C.hero : C.comp, null, 0, a);
        text(fmtN(v, v < 100 ? 1 : 0) + unit, cxL + cw, yy + 10, { role: 'label', size: 21, color: hero ? C.heroText : C.ink, align: 'right', alpha: a * kk, caps: false });
      });
    });
    /* the heat scale */
    const hx = LM, hy = 944, hk = ep(t, 3.0, 3.5);
    if (hk > 0.003) { for (let q = 0; q < 30; q++) rr(hx + q * 8, hy - 12, 8.5, 12, 0, heatCol(q / 29), null, 0, hk); text('Stress, 0 to ' + Math.round(smax) + ' MPa', hx + 260, hy, { role: 'label', size: 19, color: C.mute, alpha: hk }); }
    cursorAt(t, [[0.9, [X0 + 2 * (PW + gap) + PW / 2 + 110, Y0 + 190]], [1.6, [X0 + 2 * (PW + gap) + PW / 2 + 14, Y0 + 290]], [3.4, [X0 + 2 * (PW + gap) + PW / 2 + 14, Y0 + 298]], [9.0, [X0 + 2 * (PW + gap) + PW / 2 + 14, Y0 + 298]]], [1.65], { a: ep(t, 0.7, 1.0) });
    source(t, 'Plate FE (this deck): PP-C-20A, 13.5 GPa; skin as DKT plates, 2.3 mm ribs as T-beams; held at the four screws; 10 N on the lens ring; all 3.40 g.', { t0: 3 });
  }
});
